/* ===================== BÀI 31 · ISR, volatile và tính nguyên tử ===================== */
/* Bài 31 · ISR, volatile và tính nguyên tử (AMTS-EMB-001-M08-L03, MC51-031) — sinh bởi tools/author/mcu8051/l31.py, không sửa tay.
   Ví dụ cho trình mô phỏng 8051 và bài tập chấm tự động (đề, code mẫu, bộ thử). Lời giải không nằm ở đây. */
const PR31=[{"label":"Ví dụ: ISR cất ACC, PSW và đổi băng thanh ghi","code":"; Ví dụ 1: ISR cất ACC, PSW và dùng băng thanh ghi 1\n; Main đang tính A, B, R7 thì Timer 0 tràn (đặt để tràn\n; ngay trong lệnh MUL). ISR không được làm đổi chúng.\n        ORG     0000H\n        LJMP    MAIN\n        ORG     000BH\n        LJMP    T0ISR\n        ORG     0030H\nMAIN:   MOV     SP,#2FH                 ; ngăn xếp ra khỏi vùng băng 1-3\n        MOV     TMOD,#01H               ; Timer 0 chế độ 1\n        MOV     TH0,#0FFH               ; FFFFH: tràn ở lần đếm đầu\n        MOV     TL0,#0FFH\n        MOV     IE,#82H                 ; EA + ET0\n        MOV     A,#12H                  ; main đang tính\n        MOV     B,#3\n        MOV     R7,#3\n        SETB    TR0\n        MUL     AB                      ; A = 36H; ISR chen vào sau lệnh này\n        ADDC    A,R7                    ; main tính tiếp: 36H + 3 + CY(0)\n        CLR     TR0\n        CLR     EA\n        SJMP    $\nT0ISR:  PUSH    ACC\n        PUSH    PSW\n        MOV     PSW,#08H                ; RS0 = 1: R0..R7 là ô 08H..0FH\n        MOV     R7,#0AAH                ; R7 của băng 1 = ô 0FH\n        MOV     A,R7\n        ADD     A,#1                    ; đổi A và CY\n        MOV     40H,A\n        POP     PSW                     ; trả lại băng 0 và các cờ\n        POP     ACC\n        RETI\n        END\n","note":"Từng bước tới MUL AB: TF0 bật ở chu kỳ 18 (trong MUL), ISR được gọi ở 21 khi MUL xong. Xem ngăn xếp: 30H–31H = địa chỉ trở về 0049H, 32H = A (36H), 33H = PSW. ISR ghi R7 của băng 1 (ô 0FH = AAH), main vẫn có R7 = 03H, A = 36H + 3 = 39H. Tổng 44 chu kỳ.","dev":{"led":true},"fosc":12000000},{"label":"Lỗi: ISR quên cất A, R7, PSW","code":"; Ví dụ 2 (LỖI): ISR quên cất ngữ cảnh\n; Cùng main như ví dụ 1. ISR dùng thẳng A, R7 và ADD\n; mà không PUSH, không đổi băng: kết quả của main sai.\n        ORG     0000H\n        LJMP    MAIN\n        ORG     000BH\n        LJMP    T0ISR\n        ORG     0030H\nMAIN:   MOV     SP,#2FH\n        MOV     TMOD,#01H\n        MOV     TH0,#0FFH\n        MOV     TL0,#0FFH\n        MOV     IE,#82H\n        MOV     A,#12H\n        MOV     B,#3\n        MOV     R7,#3\n        SETB    TR0\n        MUL     AB\n        ADDC    A,R7                    ; A, R7, CY đã bị ISR đổi\n        CLR     TR0\n        CLR     EA\n        SJMP    $\nT0ISR:  MOV     R7,#0AAH                ; ghi đè R7 của main\n        MOV     A,R7                    ; ghi đè A của main\n        ADD     A,#1                    ; ghi đè CY của main\n        MOV     40H,A\n        RETI\n        END\n","note":"Cùng main, ISR không cất gì. Đoán trước: sau ADDC A,R7 thì A bằng bao nhiêu? Đúng ra là 39H, nhưng ISR để lại A = ABH, R7 = AAH nên A = ABH + AAH = 155H → A = 55H, CY = 1. Main không có cách nào biết mình đã tính sai.","dev":{"led":true},"fosc":12000000},{"label":"Lỗi: Đọc xé biến 16 bit","code":"; Ví dụ 3 (LỖI): đọc xé biến 16 bit dùng chung\n; ISR Timer 0 tăng TICK (30H byte thấp, 31H byte cao).\n; Timer 0 đặt để tràn đúng lúc main đang đọc TICK.\n        ORG     0000H\n        LJMP    MAIN\n        ORG     000BH\n        LJMP    T0ISR\n        ORG     0030H\nMAIN:   MOV     30H,#0FFH               ; TICK = 00FFH\n        MOV     31H,#00H\n        MOV     TMOD,#01H               ; Timer 0 chế độ 1\n        MOV     TH0,#0FFH               ; FFFFH: tràn ở lần đếm đầu\n        MOV     TL0,#0FFH\n        MOV     IE,#82H\n        SETB    TR0                     ; đếm từ chu kỳ sau\n        MOV     R2,30H                  ; R2 = FFH (byte thấp CŨ)\n        MOV     R3,31H                  ; ISR vừa chạy: R3 = 01H (MỚI)\n        CLR     TR0                     ; R3:R2 = 01FFH: chưa từng có!\n        CLR     EA\n        SJMP    $\nT0ISR:  PUSH    ACC\n        PUSH    PSW\n        MOV     A,30H                   ; TICK = TICK + 1 (16 bit)\n        ADD     A,#1\n        MOV     30H,A\n        CLR     A\n        ADDC    A,31H\n        MOV     31H,A\n        POP     PSW\n        POP     ACC\n        RETI\n        END\n","note":"TICK = 00FFH. Timer 0 tràn trong MOV R2,30H (cờ ở chu kỳ 16), ISR chạy ở 17 và tăng TICK thành 0100H, rồi main đọc byte cao. Kết quả R3:R2 = 01FFH: chưa từng là giá trị của TICK.","dev":{"led":true},"fosc":12000000},{"label":"Ví dụ: Đoạn găng CLR EA quanh phép đọc","code":"; Ví dụ 4: đoạn găng — tắt ngắt quanh phép đọc 16 bit\n; Nhớ EA vào CY, CLR EA, đọc 2 byte, trả EA như cũ.\n; Timer tràn trong đoạn găng: ISR bị hoãn (trễ tăng).\n        ORG     0000H\n        LJMP    MAIN\n        ORG     000BH\n        LJMP    T0ISR\n        ORG     0030H\nMAIN:   MOV     30H,#0FFH               ; TICK = 00FFH\n        MOV     31H,#00H\n        MOV     TMOD,#01H\n        MOV     TH0,#0FFH               ; FFFDH: tràn ở lần đếm thứ 3\n        MOV     TL0,#0FDH\n        MOV     IE,#82H\n        SETB    TR0\n        MOV     C,EA                    ; nhớ trạng thái EA\n        CLR     EA                      ; vào đoạn găng\n        MOV     R2,30H                  ; timer tràn trong lệnh này\n        MOV     R3,31H                  ; R3:R2 = 00FFH (nhất quán)\n        MOV     EA,C                    ; ra đoạn găng\n        NOP                             ; ISR chạy sau lệnh này\n        CLR     TR0\n        CLR     EA\n        SJMP    $\nT0ISR:  PUSH    ACC\n        PUSH    PSW\n        MOV     A,30H\n        ADD     A,#1\n        MOV     30H,A\n        CLR     A\n        ADDC    A,31H\n        MOV     31H,A\n        POP     PSW\n        POP     ACC\n        RETI\n        END\n","note":"Đoạn găng: MOV C,EA / CLR EA / hai lệnh đọc / MOV EA,C. Cờ TF0 bật ở chu kỳ 18 (giữa đoạn găng) nhưng ISR chỉ được gọi ở 24, sau NOP (lệnh ghi IE kéo thêm một lệnh). R3:R2 = 00FFH: giá trị cũ, nhất quán. Đổi lại: độ trễ ngắt tăng 6 chu kỳ.","dev":{"led":true},"fosc":12000000},{"label":"Lỗi: Vòng chờ không đọc lại biến (thiếu volatile)","code":"; Ví dụ 5 (LỖI): vòng chờ không đọc lại biến dùng chung\n; Giống mã trình dịch C sinh khi biến 'co' thiếu\n; volatile: co đọc MỘT lần vào A, vòng chờ chỉ xét A.\n        ORG     0000H\n        LJMP    MAIN\n        ORG     000BH\n        MOV     30H,#1                  ; ISR: co = 1\n        RETI\n        ORG     0030H\nMAIN:   MOV     30H,#0                  ; co = 0\n        MOV     TMOD,#02H               ; Timer 0 chế độ 2\n        MOV     TH0,#0CEH               ; 256 - 50: tràn sau 50 chu kỳ\n        MOV     TL0,#0CEH\n        MOV     IE,#82H\n        SETB    TR0\n        MOV     R7,#100                 ; chờ tối đa 100 vòng\n        MOV     A,30H                   ; đọc co một lần\nCHO:    JNZ     XONG                    ; chỉ xét A, không đọc lại 30H\n        DJNZ    R7,CHO\n        SJMP    HET                     ; hết giờ: không thấy co = 1\nXONG:   MOV     P1,#0FEH                ; thấy co = 1: bật LED P1.0\nHET:    CLR     TR0\n        CLR     EA\n        SJMP    $\n        END\n","note":"Đọc co (ô 30H) MỘT lần vào A rồi chỉ xét A. ISR đặt 30H = 1 ở chu kỳ 65 và còn chạy thêm 8 lần, nhưng vòng chờ không bao giờ thấy: hết 100 vòng, LED P1.0 không sáng (P1 = FFH), 473 chu kỳ. Đây là dạng mã trình dịch C được phép sinh khi thiếu volatile.","dev":{"led":true},"fosc":12000000}];
const sim31=makeSim51(document.getElementById("m51-l31"),{id:"s31",presets:PR31,ram:256});
makeEx51(document.getElementById("ex-l31"),"l31",[{"t":"Bật bit mà không xóa bit của ISR","d":"<p>Ô <code>20H<\/code> (gọi là CO) chứa các cờ dùng chung giữa main và ISR. ISR Timer 0 (giữ nguyên) đặt bit <code>20H.7<\/code> và tăng <code>21H<\/code>; Timer 0 được nạp để tràn sau 256 − <code>[32H]<\/code> lần đếm, tức là có thể đúng lúc main đang sửa CO. Hãy viết lại đoạn được đánh dấu để bật trong CO mọi bit có trong mặt nạ <code>30H<\/code> (CO = CO OR [30H]) mà không bao giờ làm mất bit do ISR đặt. Phần còn lại của main giữ nguyên (chờ ISR chạy xong rồi dừng).<\/p><p>Ví dụ: CO đầu = <code>00H<\/code>, <code>30H = 01H<\/code>, tràn ở lần đếm đầu → <code>20H = 81H<\/code>, <code>21H = 01H<\/code>.<\/p>","start":"; Bài 1: bật các bit của mặt nạ 30H trong ô CO (20H)\n; mà không làm mất bit 20H.7 do ISR Timer 0 đặt.\n; Timer 0 tràn sau [32H] lần đếm, giữa lúc main đang sửa.\n        ORG     0000H\n        LJMP    MAIN\n        ORG     000BH\n        SETB    20H.7                   ; ISR: báo \"có tick\"\n        INC     21H                     ; đếm số lần vào ISR\n        RETI\n        ORG     0030H\nMAIN:   MOV     20H,31H                 ; giá trị đầu của CO\n        MOV     21H,#0\n        MOV     TMOD,#01H\n        MOV     TH0,#0FFH\n        MOV     TL0,32H                 ; tràn sau 256 - [32H] lần đếm\n        MOV     IE,#82H\n        SETB    TR0\n; ---- sửa phần này: CO = CO OR [30H] ----\n        MOV     A,20H\n        ORL     A,30H\n        MOV     20H,A\n; ---- phần dưới giữ nguyên ----\nCHO:    MOV     A,21H                   ; chờ ISR chạy xong một lần\n        JZ      CHO\n        CLR     TR0\n        CLR     EA\n        SJMP    $\n        END\n","spec":{"cases":[{"setup":{"iram":{"0x30":1,"0x31":0,"0x32":255}},"expect":{"iram":{"0x20":129,"0x21":1}}},{"setup":{"iram":{"0x30":6,"0x31":16,"0x32":254}},"expect":{"iram":{"0x20":150,"0x21":1}}},{"setup":{"iram":{"0x30":0,"0x31":0,"0x32":255}},"expect":{"iram":{"0x20":128,"0x21":1}}},{"setup":{"iram":{"0x30":129,"0x31":66,"0x32":253}},"expect":{"iram":{"0x20":195,"0x21":1}}},{"setup":{"iram":{"0x30":48,"0x31":15,"0x32":255}},"expect":{"iram":{"0x20":191,"0x21":1}}},{"setup":{"iram":{"0x30":42,"0x31":85,"0x32":252}},"expect":{"iram":{"0x20":255,"0x21":1}}}]},"hints":["Chạy code mẫu với bộ thử 1 và bấm Từng bước: ISR chạy giữa lệnh đọc 20H và lệnh ghi 20H, rồi lệnh ghi đè lên bit 7 vừa được đặt.","Một lệnh đọc–sửa–ghi của 8051 (ORL direct,A; ANL direct,#; SETB bit…) chạy trọn vẹn trước khi ngắt được nhận, nên ISR không chen vào giữa được.","Cả phép OR phải nằm trong một lệnh đọc–sửa–ghi duy nhất trên ô 20H; đưa mặt nạ vào A trước."],"why":"Ngắt chỉ được nhận giữa hai lệnh. Chuỗi MOV A,20H / ORL / MOV 20H,A có hai chỗ ISR chen vào được; nếu ISR đổi 20H ở đó, lệnh ghi cuối xóa mất thay đổi của ISR (lost update). Lệnh ORL direct,A làm cả đọc, sửa, ghi trong một lệnh nên là nguyên tử đối với ngắt. Tắt ngắt quanh ba lệnh cũng đúng nhưng dài hơn và làm tăng độ trễ ngắt."},{"t":"READ16 đọc biến 16 bit không bị xé","d":"<p>ISR Timer 0 (giữ nguyên) cộng 32 vào biến 16 bit TICK (<code>30H<\/code> byte thấp, <code>31H<\/code> byte cao) mỗi 32 chu kỳ máy. Main (giữ nguyên) gọi chương trình con <code>READ16<\/code> 60 lần; mỗi lần đọc được nhỏ hơn lần trước là một lần <b>đọc xé<\/b> và được đếm ở <code>42H<\/code>. Sau vòng lặp, main tắt ngắt, gọi <code>READ16<\/code> lần nữa và ghi <code>43H = 1<\/code> nếu kết quả đúng bằng TICK. Hãy viết lại <code>READ16<\/code> (trả về R3:R2 = TICK, R2 byte thấp) để <code>42H = 0<\/code> và <code>43H = 1<\/code> với mọi pha của timer (bộ thử đặt pha lần tràn đầu ở <code>32H<\/code>).<\/p><p>Ví dụ: <code>32H = E2H<\/code> → <code>42H = 00H<\/code>, <code>43H = 01H<\/code> (code mẫu cho <code>42H = 01H<\/code>).<\/p>","start":"; Bài 2: chương trình con READ16 đọc TICK nhất quán\n; ISR Timer 0 cộng 32 vào TICK (30H thấp, 31H cao,\n; đơn vị µs) mỗi 32 chu kỳ. Main gọi READ16 60 lần;\n; lần đọc nhỏ hơn lần trước là bị xé (đếm ở 42H).\n        ORG     0000H\n        LJMP    MAIN\n        ORG     000BH\n        LJMP    T0ISR\n        ORG     0030H\nMAIN:   MOV     30H,#0                  ; TICK = 0000H\n        MOV     31H,#00H\n        MOV     42H,#0                  ; số lần đọc bị xé\n        MOV     R4,#0                   ; R5:R4 = lần đọc trước\n        MOV     R5,#0\n        MOV     TMOD,#02H               ; chế độ 2: tràn mỗi 32 chu kỳ\n        MOV     TH0,#0E0H\n        MOV     TL0,32H                 ; pha lần tràn đầu (bộ thử đặt)\n        MOV     IE,#82H\n        SETB    TR0\n        MOV     R6,#60\nLAP:    ACALL   READ16\n        CLR     C                       ; R3:R2 < R5:R4 ?\n        MOV     A,R2\n        SUBB    A,R4\n        MOV     A,R3\n        SUBB    A,R5\n        JNC     TANG\n        INC     42H                     ; đọc bị xé\nTANG:   MOV     A,R2\n        MOV     R4,A\n        MOV     A,R3\n        MOV     R5,A\n        DJNZ    R6,LAP\n        CLR     TR0\n        CLR     EA\n        ACALL   READ16                  ; ngắt đã tắt: phải đúng TICK\n        MOV     A,R2\n        XRL     A,30H\n        JNZ     SAI\n        MOV     A,R3\n        XRL     A,31H\n        JNZ     SAI\n        MOV     43H,#1                  ; 43H = 1: READ16 trả đúng TICK\nSAI:    SJMP    $\n; ---- chỉ sửa READ16 ----\nREAD16: MOV     R2,30H                  ; đọc thẳng: ISR chen vào giữa?\n        MOV     R3,31H\n        RET\nT0ISR:  PUSH    ACC\n        PUSH    PSW\n        MOV     A,30H                   ; TICK = TICK + 32 (16 bit)\n        ADD     A,#20H\n        MOV     30H,A\n        CLR     A\n        ADDC    A,31H\n        MOV     31H,A\n        POP     PSW\n        POP     ACC\n        RETI\n        END\n","spec":{"cases":[{"setup":{"iram":{"0x32":226}},"expect":{"iram":{"0x42":0,"0x43":1}}},{"setup":{"iram":{"0x32":234}},"expect":{"iram":{"0x42":0,"0x43":1}}},{"setup":{"iram":{"0x32":224}},"expect":{"iram":{"0x42":0,"0x43":1}}},{"setup":{"iram":{"0x32":244}},"expect":{"iram":{"0x42":0,"0x43":1}}},{"setup":{"iram":{"0x32":252}},"expect":{"iram":{"0x42":0,"0x43":1}}},{"setup":{"iram":{"0x32":230}},"expect":{"iram":{"0x42":0,"0x43":1}}}]},"hints":["Code mẫu đọc byte thấp rồi byte cao. Nếu ISR chạy giữa hai lệnh đúng lúc byte thấp quay vòng (E0H + 20H = 00H, nhớ 1), byte thấp là giá trị cũ còn byte cao là giá trị mới.","Cách 1: đoạn găng. Nhớ EA vào CY (MOV C,EA), CLR EA, đọc hai byte, trả EA bằng MOV EA,C. Main không dùng CY sau khi gọi nên được phép đổi CY.","Cách 2: không tắt ngắt. Đọc byte cao, đọc byte thấp, rồi kiểm byte cao có đổi không; đổi thì đọc lại từ đầu."],"why":"Volatile (đọc lại từ bộ nhớ mỗi lần) không đủ: 8051 đọc biến 16 bit bằng hai lệnh, ngắt chen được vào giữa. Cần làm cho phép đọc nguyên tử: tắt ngắt trong đoạn găng ngắn (nhớ và trả lại EA như cũ để READ16 dùng được cả khi ngắt đang tắt), hoặc đọc lại tới khi byte cao không đổi. Bộ thử cuối (43H) bảo đảm READ16 trả đúng giá trị chứ không chỉ một hằng số."},{"t":"ISR ngắn: chỉ cất cái thật sự đổi","d":"<p>Mỗi lần Timer 0 tràn (main giả lập <i>N<\/i> = <code>[30H]<\/code> lần, 0–8), ISR chép mẫu ở <code>31H<\/code> vào ô kế tiếp của bộ đệm bắt đầu ở <code>40H<\/code>. Main (phần từ <code>MOV R0,#77H<\/code> tới <code>XONG<\/code>, giữ nguyên) đang dùng <code>R0<\/code>, <code>A<\/code>, <code>B<\/code> và phải thấy chúng không đổi. Code mẫu ĐÚNG nhưng ISR cất sáu thanh ghi “cho chắc”: với <i>N<\/i> = 8 chạy 363 chu kỳ máy và dài 73 byte. Hãy viết lại ISR (được sửa cả dòng khởi tạo con trỏ) để chạy không quá <b>200 chu kỳ máy<\/b> và mã dài không quá <b>50 byte<\/b>.<\/p><p>Ví dụ: <code>30H = 3<\/code> → <code>40H..42H = 03H 02H 01H<\/code>, <code>R0 = 77H<\/code>, <code>A = 5AH<\/code>, <code>B = A5H<\/code>.<\/p>","start":"; Bài 3: ISR ghi mẫu vào bộ đệm — cắt bớt lưu ngữ cảnh\n; Mỗi lần Timer 0 tràn (giả lập N = [30H] lần), ISR chép\n; mẫu ở 31H vào ô kế tiếp của bộ đệm từ 40H. Code mẫu\n; ĐÚNG nhưng cất mọi thứ \"cho chắc\": chậm và dài.\n        ORG     0000H\n        LJMP    MAIN\n        ORG     000BH\n        LJMP    T0ISR\n        ORG     0030H\nMAIN:   MOV     SP,#5FH                 ; ngăn xếp từ 60H, xa vùng dữ liệu\n        MOV     3FH,#40H                ; con trỏ bộ đệm (được sửa)\n; ---- từ đây tới XONG giữ nguyên ----\n        MOV     R0,#77H                 ; main đang dùng R0, A, B\n        MOV     A,#5AH\n        MOV     B,#0A5H\n        MOV     IE,#82H\n        MOV     R7,30H                  ; N lần (0-8)\n        CJNE    R7,#0,LAP\n        SJMP    XONG\nLAP:    MOV     31H,R7                  ; mẫu lần này = R7\n        SETB    TF0                     ; giả lập Timer 0 tràn\n        NOP                             ; ISR chạy sau lệnh này\n        DJNZ    R7,LAP\nXONG:   CLR     EA\n        SJMP    $\n; ---- ISR: được viết lại tùy ý ----\nT0ISR:  PUSH    ACC\n        PUSH    PSW\n        PUSH    B\n        PUSH    DPL\n        PUSH    DPH\n        PUSH    00H                     ; R0 của băng 0\n        MOV     R0,3FH\n        MOV     A,31H\n        MOV     @R0,A\n        INC     R0\n        MOV     3FH,R0\n        POP     00H\n        POP     DPH\n        POP     DPL\n        POP     B\n        POP     PSW\n        POP     ACC\n        RETI\n        END\n","spec":{"cases":[{"setup":{"iram":{"0x30":3}},"expect":{"iram":{"0x40":3,"0x41":2,"0x42":1,"0x43":0},"regs":{"R0":119,"A":90,"B":165}}},{"setup":{"iram":{"0x30":0}},"expect":{"iram":{"0x40":0},"regs":{"R0":119,"A":90,"B":165}}},{"setup":{"iram":{"0x30":1}},"expect":{"iram":{"0x40":1,"0x41":0},"regs":{"R0":119,"A":90,"B":165}}},{"setup":{"iram":{"0x30":8}},"expect":{"iram":{"0x40":8,"0x41":7,"0x42":6,"0x43":5,"0x44":4,"0x45":3,"0x46":2,"0x47":1,"0x48":0},"regs":{"R0":119,"A":90,"B":165}}},{"setup":{"iram":{"0x30":5}},"expect":{"iram":{"0x40":5,"0x41":4,"0x42":3,"0x43":2,"0x44":1,"0x45":0},"regs":{"R0":119,"A":90,"B":165}}},{"setup":{"iram":{"0x30":2}},"expect":{"iram":{"0x40":2,"0x41":1,"0x42":0},"regs":{"R0":119,"A":90,"B":165}}}],"maxCyc":200,"maxBytes":50},"hints":["ISR này không dùng B, DPL, DPH: bỏ PUSH/POP của chúng. MOV @Ri,direct chép thẳng 31H vào bộ đệm, không cần qua A.","Con trỏ bộ đệm có thể nằm luôn trong R0 của băng thanh ghi 1 (ô 08H): khởi tạo MOV 08H,#40H, rồi trong ISR PUSH PSW, MOV PSW,#08H … POP PSW. R0 của băng 1 giữ giá trị giữa các lần ngắt.","Đặt ISR ngay tại vectơ 000BH (bỏ LJMP: đỡ 2 chu kỳ mỗi lần và 3 byte). ISR được tràn qua 0013H vì INT1 không được dùng."],"why":"Mỗi PUSH/POP tốn 2 chu kỳ và 2 byte, nhân với số lần ngắt. ISR chỉ cần cất những gì nó thực sự đổi. Đổi băng thanh ghi (PSW.3, PSW.4) cho ISR một bộ R0–R7 riêng chỉ với PUSH PSW + MOV PSW,#… và POP PSW; thanh ghi của băng riêng còn giữ được trạng thái giữa các lần ngắt (con trỏ, bộ đếm). Lời giải mẫu: 171 chu kỳ, 48 byte."}]);

makeQuiz("quiz31","score31",[{"q": "Khi 8051 vào ngắt, phần cứng tự cất những gì lên ngăn xếp?", "o": ["PC và PSW", "PC, A và PSW", "Toàn bộ R0–R7 của băng đang dùng", "Chỉ PC (2 byte)"], "a": 3, "e": "Lệnh gọi do phần cứng chỉ đẩy PC. A, PSW, B, DPTR, R0–R7 phải được ISR tự cất (PUSH hoặc đổi băng thanh ghi) nếu ISR làm đổi chúng (ví dụ 1, 2)."}, {"q": "Biến 16 bit tick được khai báo volatile và ISR tăng nó. Main đọc tick bằng t = tick; trên 8051. Phát biểu nào đúng?", "o": ["Không thể đọc xé vì volatile tắt ngắt khi đọc", "Vẫn có thể đọc xé: volatile chỉ bắt đọc bộ nhớ mỗi lần, không làm phép đọc 2 byte thành nguyên tử", "Không thể đọc xé vì trình dịch dùng một lệnh 16 bit", "Chỉ đọc xé khi thiếu volatile"], "a": 1, "e": "8051 không có lệnh đọc 16 bit từ RAM trong; SDCC sinh hai lệnh mov dpl,_tick / mov dph,(_tick + 1). Ngắt chen vào giữa vẫn được: cần đoạn găng hoặc đọc lại tới khi khớp."}, {"q": "ISR đặt bit 20H.7. Main cần bật bit 20H.0. Đoạn nào an toàn mà không cần tắt ngắt?", "o": ["MOV A,20H / ORL A,#01H / MOV 20H,A", "ORL 20H,#01H", "MOV A,20H / SETB ACC.0 / MOV 20H,A", "Cả ba đều an toàn vì mỗi lệnh đều ngắn"], "a": 1, "e": "Ngắt chỉ được nhận giữa hai lệnh. ORL 20H,#01H đọc, sửa, ghi trong một lệnh nên ISR không chen vào được. Chuỗi 3 lệnh để ISR chen vào giữa lần đọc và lần ghi: lệnh ghi cuối xóa bit 7. (SETB 20H.0 cũng an toàn.)"}, {"q": "Vì sao đoạn găng viết MOV C,EA / CLR EA / … / MOV EA,C thay vì CLR EA / … / SETB EA?", "o": ["Vì SETB EA không được phép trên 8051", "Vì MOV EA,C chạy nhanh hơn SETB EA", "Để đoạn găng không bật ngắt lên khi nơi gọi đang tắt ngắt sẵn", "Để xóa cờ TF0 đang chờ"], "a": 2, "e": "Nếu đoạn mã được gọi lúc EA = 0 (trong một đoạn găng khác, hoặc lúc khởi động), SETB EA sẽ bật ngắt sai chỗ. Nhớ EA vào CY rồi trả lại giữ nguyên trạng thái của nơi gọi. Đổi lại CY bị đổi, nên nơi gọi không được cần CY."}, {"q": "Trong đoạn găng, Timer 0 tràn. Điều gì xảy ra với ngắt đó?", "o": ["Cờ TF0 vẫn giữ; ISR chạy sau khi EA được bật lại (và thêm một lệnh), nên bị trễ", "Ngắt bị mất vì EA = 0", "ISR chạy ngay vì Timer 0 có ưu tiên cao", "Timer 0 dừng đếm cho tới khi EA = 1"], "a": 0, "e": "EA chỉ chặn việc CPU nhận ngắt, không chặn cờ. Ví dụ 4: TF0 bật ở chu kỳ 18, ISR gọi ở 24. Nếu đoạn găng dài tới mức timer tràn hai lần, lần thứ hai mới bị mất (Bài 32)."}]);

